function pixelArt(kind,id,known=true,large=false){if(kind==='meal'&&typeof E!=='undefined')id=(E.recipe(id)||E.dish(id))?.art||id;if(known&&typeof E!=='undefined'&&animalArt.has(id)){const size=animalArtSizes[id],scale=size?90/Math.max(...size):0,fit=size?'--art-width:'+size[0]*scale+'%;--art-height:'+size[1]*scale+'%;':'';return '<span class="pixel-art pixel-kind-animal '+(large?'pixel-large':'')+'" aria-hidden="true" style="background-image:url(assets/animal-'+id+'.webp);--art-size:100% 100%;--art-position:center;'+fit+'"></span>'}const slot=pixelSlots[kind]?.[id];if(!known||slot===undefined)return '';const tile=slot%16,sheet=Math.floor(slot/16)+1,x=tile%4*100/3,y=Math.floor(tile/4)*100/3,special=kind==='meal'&&id==='fishhead-pot'?' pixel-meal-fishhead':'',atlas=pixelBounds[sheet],r=atlas.rects[tile],scale=90/Math.max(r[2],r[3]),crop=special?'':'--art-width:'+r[2]*scale+'%;--art-height:'+r[3]*scale+'%;--art-size:'+atlas.width/r[2]*100+'% '+atlas.height/r[3]*100+'%;--art-position:'+r[0]/(atlas.width-r[2])*100+'% '+r[1]/(atlas.height-r[3])*100+'%;';return '<span class="pixel-art pixel-kind-'+kind+' pixel-sheet-'+sheet+special+' '+(large?'pixel-large':'')+'" aria-hidden="true" style="background-position:'+x+'% '+y+'%;'+crop+(sheet===18?'background-image:url(assets/pixel-atlas-18-clear.webp);':sheet>=13?'background-image:url(assets/sprites16/'+kind+'-'+id+'.webp'+');--art-size:100% 100%;--art-position:center;':'')+'"></span>'}
function atlasPlantRows(list){return list.length?'<div class="picker-group">水生與濱水植物<small>'+list.length+' 種</small></div><div class="item-picker-grid">'+list.map(x=>'<button class="item-chip atlas-chip '+(atlasPicked==='plant:'+x.id?'active':'')+' '+(E.plantKnown(state,x.id)?'':'unrecorded')+'" data-all-plant-pick="'+x.id+'" aria-pressed="'+(atlasPicked==='plant:'+x.id)+'">'+pixelArt('plant',x.id,E.plantKnown(state,x.id))+'<span>'+E.plantName(state,x.id)+'</span><small>'+(E.plantKnown(state,x.id)?'已採集':E.plantWaters(x.id).map(r=>r.name).join('・'))+'</small></button>').join('')+'</div>':''}
