// Kitchen: a recipe is listed once any of its fish has been caught; locked recipes are only counted.
function kitchenUnlocked(r){return E.recipeUnlocked(state,r)}
function kitchenHeld(r){return E.recipeMaterials(r).map(m=>[m.id,E.materialCount(state,m)]).filter(([,n])=>n)}
function kitchenChoice(r){const held=kitchenHeld(r).map(([id])=>id),want=kitchenFish[r.id];return held.includes(want)?want:held.includes(kitchenFocus)?kitchenFocus:held[0]||null}
function kitchenBlock(r){const s=state;if(!kitchenHeld(r).length)return '缺少材料';if(!E.canSpend(s,r.cost,1))return s.money<r.cost?'旅費不足':`需保留 ${E.reserve()} 元魚餌費`;return ''}
function kitchenReady(r){return kitchenHeld(r).length&&E.canSpend(state,r.cost,1)}
function buffName(s){return E.mealName(s.buff)}
function confirmMeal(s){E.settle(s);return !s.buff||confirm(FishingLanguage.text(`目前的${buffName(s)}效果還剩 ${s.buff.left} 竿，享用新料理會取代這個效果。確定要享用嗎？`))}
function openKitchenFor(key){const pl=isWeedKey(key),id=pl?key.slice(5):key,f=pl?E.plant(id):E.fish(id),r=D.recipes.find(r=>r.fish!=='*'&&E.recipeMaterials(r).some(m=>m.id===id&&m.type===(pl?'plant':'species')));if(!f||(!pl&&!f.cookable)||pl&&!r)return;kitchenMode='home';kitchenFocus=id;kitchenQuery=f.name;kitchenFilter='all';kitchenPicked=(r||E.recipe('panfry')).id;kitchenSheetOpen=collectionMobile();switchTab('kitchen')}
// Restaurant dishes of the current water: bought with money, no fish needed.
function dineBlock(d){const s=state;if(!E.canSpend(s,d.price))return s.money<d.price?'旅費不足':`需保留 ${E.reserve()} 元魚餌費`;return ''}
const tierLabel=d=>d.tier==='basic'?'小吃':D.recipeTiers[d.tier].name;
// 0.23 kitchen: the active meal shows as a banner only while it lasts; rules moved to the settings guide.
function renderBuffBanner(){const s=state,b=$('kitchenBuff'),m=s.buff&&(E.recipe(s.buff.id)||E.dish(s.buff.id));b.hidden=!m;b.innerHTML=m?`<span class="tag">生效中</span><strong>${buffName(s)}</strong><span>${m.desc.split('，')[0]}</span><span class="muted">剩 ${s.buff.left} 竿</span><span class="buff-note">再吃一道會取代目前效果</span>`:''}
function renderKitchen(){const s=state;if(!$('kitchenSearch')){$('kitchen').innerHTML=`<div id="kitchenBuff" class="buff-banner" role="status" hidden></div><div class="kitchen-bar"><div id="kitchenModes"></div><div id="kitchenTabs"></div><div class="collection-tools"><input id="kitchenSearch" type="search" placeholder="搜尋料理或材料" aria-label="搜尋料理或材料"></div></div><div id="kitchenCollection"></div>`;$('kitchenSearch').oninput=e=>{kitchenQuery=e.target.value;kitchenSheetOpen=false;renderKitchen()}}
 if($('kitchenSearch').value!==kitchenQuery)$('kitchenSearch').value=kitchenQuery;
 const shop=D.restaurants[s.region];$('kitchenModes').innerHTML=`<div class="collection-tabs kitchen-modes" role="group" aria-label="料理來源"><button data-kitchen-mode="home" aria-pressed="${kitchenMode==='home'}">自己做</button><button data-kitchen-mode="dine" aria-pressed="${kitchenMode==='dine'}">當地餐廳・${shop.name}</button></div>`;document.querySelectorAll('[data-kitchen-mode]').forEach(b=>b.onclick=()=>{if(kitchenMode===b.dataset.kitchenMode)return;kitchenMode=b.dataset.kitchenMode;kitchenFilter='all';kitchenQuery='';kitchenSheetOpen=false;renderKitchen()});
 renderBuffBanner();if(kitchenMode==='dine')return renderDining();
 const unlocked=D.recipes.filter(kitchenUnlocked),q=FishingLanguage.simplify(kitchenQuery.trim());
 $('kitchenTabs').innerHTML=collectionTabs('kitchen',kitchenFilter,[['all','全部'],['ready','可製作'],...mealLabels.filter(([k])=>unlocked.some(r=>r.effect===k))]);document.querySelectorAll('[data-kitchen-filter]').forEach(b=>b.onclick=()=>{kitchenFilter=b.dataset.kitchenFilter;kitchenSheetOpen=false;renderKitchen()});
 const matches=r=>!q||FishingLanguage.simplify(r.name+(r.orig||'')+r.origin).includes(q)||E.recipeMaterials(r).some(m=>E.materialKnown(s,m)&&FishingLanguage.simplify(m.name+(m.other||'')).includes(q));
 const list=unlocked.filter(r=>(kitchenFilter==='all'||kitchenFilter==='ready'&&kitchenReady(r)||r.effect===kitchenFilter)&&matches(r));
 if(!list.some(r=>r.id===kitchenPicked)){kitchenPicked=list[0]?.id||null;kitchenSheetOpen=false}
 const r=E.recipe(kitchenPicked);let detail='<p class="empty">沒有符合條件的料理。</p>';
 if(r){const held=kitchenHeld(r),pick=kitchenChoice(r),block=kitchenBlock(r),fishLine=r.materialNote||(r.fish==='*'?'魚':E.recipeMaterials(r).map(m=>E.materialKnown(s,m)?m.name:m.type==='plant'?'未採集水草':'未捕獲魚種').join('、'));detail=`<div class="detail-head"><div><span class="tag">${r.origin} · ${D.recipeTiers[r.tier].name}</span><h2>${r.name}${r.orig&&r.orig!==r.name?`<small>${r.orig}</small>`:''}</h2></div>${closeButton()}</div>${pixelArt('meal',r.id,true,true)}<p class="detail-description">${r.about}</p><div class="meal-facts"><p><span>效果</span>${mealEffect(r)}</p><p><span>需要</span>${fishLine} ×1${r.plants?' 團':''} ＋ 佐料 ${r.cost} 元</p></div>${held.length>1?`<label class="kitchen-fish">選擇材料 <select id="kitchenFishSelect">${held.map(([id,n])=>`<option value="${id}" ${id===pick?'selected':''}>${E.recipeMaterials(r).find(m=>m.id===id).name}（持有 ${n}）</option>`).join('')}</select></label>`:held.length?'':'<p class="muted">漁獲箱裡沒有可用的材料。</p>'}${mealHintHTML(r)}<div class="detail-actions"><button id="kitchenCook" class="${block?'':'primary'}" ${block?'disabled':''}>${block||`製作並享用 · ${r.cost} 元`}</button></div>`}
 const locked=D.recipes.length-unlocked.length,groups=D.cuisines.map(([key,label])=>[label,list.filter(x=>x.cuisine===key)]).filter(([,a])=>a.length);
 $('kitchenCollection').innerHTML=`<div class="collection-layout"><div id="kitchenList" class="item-picker">${list.length?groups.map(([label,a])=>`<div class="picker-group">${label}<small>${a.length} 道</small></div><div class="item-picker-grid">${a.map(x=>{return `<button class="item-chip kitchen-chip ${x.id===kitchenPicked?'active':''} ${kitchenReady(x)?'ready':'unavailable'}" data-kitchen-pick="${x.id}" aria-pressed="${x.id===kitchenPicked}">${pixelArt('meal',x.id)}<span>${x.name}<small>${mealShort[x.effect]}${x.tier==='classic'?' · 名菜':''}</small></span></button>`}).join('')}</div>`).join(''):'<p class="empty">沒有符合條件的料理。</p>'}${locked?`<p class="kitchen-locked">還有 ${locked} 道料理，捕獲對應材料後解鎖。</p>`:''}</div>${detailShell('kitchen',detail,kitchenSheetOpen&&!!r)}</div>`;
 document.querySelectorAll('[data-kitchen-pick]').forEach(b=>b.onclick=()=>{kitchenPicked=b.dataset.kitchenPick;kitchenSheetOpen=true;renderKitchen();if(collectionMobile())$('kitchenDetail').querySelector('.detail-close')?.focus({preventScroll:true})});
 if(r){if($('kitchenFishSelect'))$('kitchenFishSelect').onchange=e=>{kitchenFish[r.id]=e.target.value;renderKitchen()};$('kitchenCook').onclick=()=>confirmMeal(s)&&act(()=>E.cook(s,r.id,Date.now(),kitchenChoice(r)))}bindDetailClose('kitchen')}
// 0.23: per-category progress sits on the tabs, replacing the old summary boxes.
function renderAtlasTabs(){const p=E.collectionProgress(state),n=k=>{const l=D.species.filter(f=>isFishCategory(f,k));return l.filter(f=>E.known(state,f.id)).length+'/'+l.length};$('atlasTabs').innerHTML=collectionTabs('atlas',atlasFilter,[['all','全部',p.caught+'/'+p.total],['fresh','淡水魚'],['brackish','河口魚'],['sea','海水魚'],['invasive','入侵種'],['crustacean','蝦蟹'],['cephalopod','頭足類'],['jellyfish','水母'],['plant','植物',p.plants.caught+'/'+p.plants.total]].map(([k,label,count])=>[k,label+' <small>'+(count||n(k))+'</small>']));document.querySelectorAll('[data-atlas-filter]').forEach(b=>b.onclick=()=>{atlasFilter=b.dataset.atlasFilter;atlasSheetOpen=false;renderAtlas()})}
// Water plant atlas: same list and detail layout as the fish atlas; uncollected plants show their waters as clues.
function plantRarity(r,id){const share=r.weeds[id]/Object.values(r.weeds).reduce((a,w)=>a+w,0);return share>=.4?'常見':share>=.25?'普通':'少見'}
function renderPlants(){const s=state,known=Object.keys(s.plants).length,list=D.plants.filter(p=>E.plantMatches(s,p,atlasQuery)&&(!$('atlasKnown').checked||E.plantKnown(s,p.id)));if(!list.some(p=>p.id===plantPicked)){plantPicked=list[0]?.id||null;atlasSheetOpen=false}
 $('atlasProgressLabel').textContent='植物收集';$('atlasProgress').textContent=`${known} / ${D.plants.length} 種`;$('atlasProgressBar').style.width=known/D.plants.length*100+'%';
 const waters=E.regionMatches(atlasQuery);$('atlasWaterNote').hidden=!waters.length;$('atlasWaterNote').textContent=waters.map(r=>{const ids=Object.keys(r.weeds);return `${r.name}：已採集 ${ids.filter(id=>E.plantKnown(s,id)).length}／${ids.length} 種植物`}).join('；');renderAtlasTabs();
 const p=E.plant(plantPicked);let detail='<p class="empty">沒有符合條件的植物。</p>';
 detail=plantDetail(p);atlasSummary();
 const groups=[['fresh','淡水'],['brackish','半淡鹹水'],['sea','海水']].map(([key,label])=>[key,label,list.filter(x=>x.water===key)]);
 $('atlasCollection').innerHTML=`<div class="collection-layout"><div id="atlasList" class="item-picker">${list.length?groups.filter(([,,a])=>a.length).map(([key,label,a])=>`<div class="picker-group">${label}<small>${a.filter(x=>E.plantKnown(s,x.id)).length}／${a.length} 種</small></div><div class="item-picker-grid">${a.map(x=>`<button class="item-chip atlas-chip ${x.id===plantPicked?'active':''} ${E.plantKnown(s,x.id)?'':'unrecorded'}" data-plant-pick="${x.id}" aria-pressed="${x.id===plantPicked}">${pixelArt('plant',x.id,E.plantKnown(s,x.id))}<span>${E.plantName(s,x.id)}</span><small>${E.plantKnown(s,x.id)?'已採集':E.plantWaters(x.id).map(r=>r.name).join('・')}</small></button>`).join('')}</div>`).join(''):'<p class="empty">沒有符合條件的植物。</p>'}</div>${detailShell('atlas',detail,atlasSheetOpen&&!!p)}</div>`;
 document.querySelectorAll('[data-plant-pick]').forEach(b=>b.onclick=()=>{plantPicked=b.dataset.plantPick;atlasSheetOpen=true;renderAtlas();if(collectionMobile())$('atlasDetail').querySelector('.detail-close')?.focus({preventScroll:true})});bindDetailClose('atlas')}
function renderDining(){const s=state,shop=D.restaurants[s.region],q=FishingLanguage.simplify(kitchenQuery.trim());
 $('kitchenTabs').innerHTML=collectionTabs('kitchen',kitchenFilter,[['all','全部'],['ready','可點餐'],...mealLabels.filter(([k])=>shop.dishes.some(d=>d.effect===k))]);document.querySelectorAll('[data-kitchen-filter]').forEach(b=>b.onclick=()=>{kitchenFilter=b.dataset.kitchenFilter;kitchenSheetOpen=false;renderKitchen()});
 const list=shop.dishes.filter(d=>(kitchenFilter==='all'||kitchenFilter==='ready'&&!dineBlock(d)||d.effect===kitchenFilter)&&(!q||FishingLanguage.simplify(d.name+(d.orig||'')).includes(q)));
 if(!list.some(d=>d.id===kitchenPicked)){kitchenPicked=list[0]?.id||null;kitchenSheetOpen=false}
 const d=E.dish(kitchenPicked);let detail='<p class="empty">沒有符合條件的菜色。</p>';
 if(d){const block=dineBlock(d);detail=`<div class="detail-head"><div><span class="tag">${E.region(d.region).name}・${shop.name} · ${tierLabel(d)}</span><h2>${d.name}${d.orig?`<small>${d.orig}</small>`:''}</h2></div>${closeButton()}</div>${pixelArt('meal',d.id,true,true)}<p class="detail-description">${d.about}</p><div class="meal-facts"><p><span>效果</span>${mealEffect(d)}</p><p><span>價格</span>${d.price} 元</p></div>${mealHintHTML(d)}<div class="detail-actions"><button id="kitchenDine" class="${block?'':'primary'}" ${block?'disabled':''}>${block||`點餐 · ${d.price} 元`}</button></div>`}
 $('kitchenCollection').innerHTML=`<div class="collection-layout"><div id="kitchenList" class="item-picker">${list.length?`<div class="picker-group">${shop.name}<small>${list.length} 道</small></div><div class="item-picker-grid">${list.map(x=>`<button class="item-chip kitchen-chip ${x.id===kitchenPicked?'active':''} ${dineBlock(x)?'':'ready'}" data-kitchen-pick="${x.id}" aria-pressed="${x.id===kitchenPicked}">${pixelArt('meal',x.id)}<span>${x.name}<small>${mealShort[x.effect]} · ${tierLabel(x)}</small></span><b>${x.price} 元</b></button>`).join('')}</div>`:'<p class="empty">沒有符合條件的菜色。</p>'}</div>${detailShell('kitchen',detail,kitchenSheetOpen&&!!d)}</div>`;
 document.querySelectorAll('[data-kitchen-pick]').forEach(b=>b.onclick=()=>{kitchenPicked=b.dataset.kitchenPick;kitchenSheetOpen=true;renderKitchen();if(collectionMobile())$('kitchenDetail').querySelector('.detail-close')?.focus({preventScroll:true})});
 if(d)$('kitchenDine').onclick=()=>confirmMeal(s)&&act(()=>E.dine(s,d.id));bindDetailClose('kitchen')}

function plantDetail(p){const s=state;let detail='<p class="empty">沒有符合條件的植物。</p>'; if(p&&E.plantKnown(s,p.id))detail=`<div class="detail-head"><div><span class="tag">${p.type}</span><h2>${p.name}</h2></div>${closeButton()}</div>${pixelArt('plant',p.id,true,true)}<em class="fish-latin">${p.latin}</em>${p.other?`<p class="muted">別名：${p.other}</p>`:''}<div class="detail-stats"><div><span>採集紀錄</span><strong>${s.plants[p.id]} ${(p.unit||(p.drift?'枝':'團'))}</strong></div><div><span>回收價</span><strong>每${(p.unit||(p.drift?'枝':'團'))} 3 元</strong></div></div><dl class="fish-description"><dt>辨識特徵</dt><dd>${p.form}</dd><dt>生長環境</dt><dd>${p.habitat}</dd><dt>分布</dt><dd>${p.distribution}</dd>${(p.localNames||[]).map(([lang,n])=>`<dt>${lang}</dt><dd>${n}</dd>`).join('')}${D.recipes.some(r=>r.plants?.includes(p.id))?`<dt>遊戲料理</dt><dd>可製作${D.recipes.filter(r=>r.plants?.includes(p.id)).map(r=>r.name).join('、')}。 <button class="text-link" data-plant-cook="${p.id}">前往料理 ›</button></dd>`:''}<dt>遊戲水域</dt><dd>${E.plantWaters(p.id).map(r=>`${r.name}（${plantRarity(r,p.id)}）`).join('、')}</dd></dl><a href="${p.source}" target="_blank" rel="noreferrer" class="source-link">植物資料來源 ↗</a>`;
 else if(p){const ws=E.plantWaters(p.id);detail=`<div class="detail-head"><div><span class="tag">尚未採集 · 獲得線索</span><h2>${E.plantName(s,p.id)}</h2></div>${closeButton()}</div><div class="detail-stats"><div><span>出沒水域</span><strong>${ws.map(r=>r.name).join('、')}</strong></div><div><span>出現頻率</span><strong>${ws.map(r=>plantRarity(r,p.id)).join('／')}</strong></div><div><span>類型</span><strong>${p.type}</strong></div></div>`}
return detail}


function catchTooltip(f){const c=E.clues(f.id);return '<i id="catch-tip-'+f.id+'" class="catch-tooltip" role="tooltip">水域：'+c.waters.map(w=>esc(w.name)).join('、')+'<br>餌料：'+esc(c.bait)+'</i>'}
function speciesDetail(f){const clue=E.clues(f.id),known=E.known(state,f.id);if(!known)return '<div class="detail-head"><div><span class="tag">尚未捕獲</span><h2>'+E.catalogName(state,f.id)+'</h2></div>'+closeButton()+'</div><p class="detail-description clue-hint">'+esc(clue.hint)+'</p><div class="detail-stats"><div><span>水域</span><strong>'+clue.waters.map(w=>esc(w.name)).join('、')+'</strong></div><div><span>餌料</span><strong>'+esc(clue.bait)+'</strong></div><div><span>出現頻率</span><strong>'+clue.waters.map(w=>w.rarity).join('／')+'</strong></div><div><span>體型</span><strong>'+clue.size+'</strong></div>'+(clue.rod?'<div><span>釣竿</span><strong>'+clue.rod+'</strong></div>':'')+'</div>'+(clue.condition?'<p class="detail-reward">'+esc(clue.condition)+'</p>':'');
const record=f.category?state.animals[f.id]:state.book[f.id],unit=f.category?'隻':'尾',names=(f.localNames||[]).map(([lang,n])=>'<dt>'+esc(lang)+'</dt><dd>'+esc(n)+'</dd>').join(''),meals=f.cookable?D.recipes.filter(r=>r.fishes.includes(f.id)).map(r=>E.recipeName(r,f.id)).join('、'):'';return '<div class="detail-head fish-heading"><div><span class="tag">'+esc(f.kind)+'</span><h2'+(f.signature?' class="signature-name"':'')+'>'+FishingLanguage.annotate(f.name)+'</h2><div class="fish-meta"><em class="fish-latin">'+esc(f.latin)+'</em>'+(f.other?'<p class="muted">俗名：'+FishingLanguage.annotate(f.other)+'</p>':'')+FishingLanguage.readingHTML(f)+(names?'<dl class="local-names">'+names+'</dl>':'')+'</div></div>'+pixelArt('fish',f.id,true,true)+closeButton()+'</div><div class="detail-stats"><div><span>捕獲紀錄</span><strong>'+record.count+' '+unit+'</strong></div><div><span>最大重量</span><strong>'+record.best.toFixed(f.category?3:2)+' 公斤</strong></div>'+(f.bounty?'<div class="bounty-stat"><span>賞金</span><strong>每'+(f.category?'隻':'尾')+' '+Math.round(f.bounty*E.saleMultiplier(state))+' 元</strong></div>':'')+'</div>'+(f.intro?'<p class="detail-description species-intro">'+esc(f.intro)+'</p>':'')+'<dl class="fish-description"><dt>辨識特徵</dt><dd>'+esc(f.form)+'</dd><dt>棲地與食性</dt><dd>'+esc(f.habitat+f.diet)+'</dd><dt>分布</dt><dd>'+esc(f.distribution)+'</dd>'+''+(meals?'<dt>遊戲料理</dt><dd>'+meals+'</dd>':'')+'<dt>水域</dt><dd>'+clue.waters.map(w=>esc(w.name)).join('、')+'</dd><dt>餌料</dt><dd>'+esc(clue.bait)+'</dd>'+(clue.rod?'<dt>釣竿</dt><dd>'+clue.rod+'</dd>':'')+(clue.condition?'<dt>出沒條件</dt><dd>'+esc(clue.condition)+'</dd>':'')+(f.bounty?'<dt>遊戲賞金</dt><dd>懸賞地點：'+esc(E.bountyPlaces(f.id))+'。身在懸賞地點時，可在漁獲箱的「可繳賞金」繳交；在哪裡釣到都可以，金額隨漁獲售價升級提高。</dd>':'')+'</dl><a href="'+esc(f.source)+'" target="_blank" rel="noreferrer" class="source-link">資料來源 ↗</a>'}

// Effect labels for the kitchen tabs and list chips.
const mealLabels=[['speed','加快等待'],['lure','誘新'],['weed','避草'],['bait','省餌'],['double','雙收'],['night','不分晝夜'],['animal','水生動物']],mealShort=Object.fromEntries(mealLabels);
// Live note on what the meal does in the current water and with the selected bait.
function mealHintHTML(m){const h=E.mealHint(state,m.id);return h?`<p class="meal-hint${h.idle?' idle':''}">${h.text}</p>`:''}
// Meal detail: effect on the first line, duration on its own line.
function mealEffect(m){return m.desc.split('，')[0]+'，維持 '+m.casts+' 竿'}

document.addEventListener('click',e=>{const b=e.target.closest('[data-plant-cook]');if(b){closeCollections();openKitchenFor('weed:'+b.dataset.plantCook)}});
